create temp table _c on commit drop as
 select fid,'t'::text soort,unnest(t) naam from _v union all select fid,'d',unnest(d) from _v union all select fid,'r',unnest(r) from _v;
do $$ declare v int; begin
  select count(*) into v from _c c where (c.soort='t' and not exists (select 1 from public.themas x where x.naam=c.naam)) or (c.soort='d' and not exists (select 1 from public.doelgroepen x where x.naam=c.naam)) or (c.soort='r' and not exists (select 1 from public.regios x where x.naam=c.naam));
  if v>0 then raise exception '% onbekende taxonomiewaarden', v; end if;
end $$;
insert into public.funder_themas (funder_id, thema_id) select c.fid, t.id from _c c join public.funders f on f.id=c.fid join public.themas t on t.naam=c.naam where c.soort='t' on conflict do nothing;
insert into public.funder_doelgroepen (funder_id, doelgroep_id) select c.fid, d.id from _c c join public.funders f on f.id=c.fid join public.doelgroepen d on d.naam=c.naam where c.soort='d' on conflict do nothing;
insert into public.funder_regios (funder_id, regio_id) select c.fid, g.id from _c c join public.funders f on f.id=c.fid join public.regios g on g.naam=c.naam where c.soort='r' on conflict do nothing;
